  "usage_notes": [
    {
      "chord_quality": "maj7",
      "function_role": "voicing-density-pairing",
      "narrative": "For maj7 chords (Cmaj7 and Fmaj7 in C major, Abmaj7 in C harmonic minor), Goodrick catalogs both Close and Spread voicings as paired entries across every cycle; practice the same diatonic root-motion sequence in both density positions and observe which voice carries the common tone (the major seventh resolving up by half-step or held). Chapter 1, pp. 12-189.",
      "source_work_id": "almanac-vol-1",
      "references": [
