      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "aug-triad",
      "function_role": "voicing-density-pairing",
      "narrative": "Augmented triads arise diatonically from C harmonic minor (III+, Eb+) and C melodic minor; like dim7, they are symmetric (all major thirds), so Close and Spread voicings are inversional equivalents. Goodrick's paired catalog entries expose the three enharmonically equivalent root positions, allowing the guitarist to choose the most ergonomic fingering for each cycle's root-motion context. Chapter 1, pp. 12-189.",
      "source_work_id": "almanac-vol-1",
      "references": [
        {
          "source": "almanac-vol-1",
          "citation": "Chapter 1 pp.12-189"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
